def _proof_module():
    """Import the concurrently developed proof contract only when invoked."""
    from . import proof_capsule
    return proof_capsule


def _measure_public_page(url: str, language: Language) -> dict[str, Any]:
    """Enter the proof module through its URL-only trust boundary."""
    module = _proof_module()
    measure = getattr(module, "measure_public_page", None)
    if not callable(measure):
        raise RuntimeError("trusted measurement entry point is unavailable")
    result = measure(url, surface=SURFACE, language=language)
    if not isinstance(result, dict) or set(result) != {
        "check", "capsule", "proof_status",
    }:
        raise RuntimeError("trusted measurement result is not closed")
    if result.get("proof_status") not in {
        "verified", "not_applicable", "unavailable",
    }:
        raise RuntimeError("trusted measurement proof state is invalid")
    return result


def _validate_proof(cap: dict[str, Any]) -> list[str]:
    module = _proof_module()
    validator = getattr(module, "validate", None)
    if not callable(validator):
        return ["proof_validator_unavailable"]
    result = validator(cap, surface=SURFACE)
    return list(result or [])


def _base_result(check: dict[str, Any], *, status: ToolStatus,
                 proof_status: ProofStatus, ok: bool,
                 language: Language = "ar",
                 errors: list[str] | None = None) -> dict[str, Any]:
    return {
        "schema": "advisors.store-readiness-tool/v1",
        "ok": ok,
        "status": status,
        "measurement_status": str(check.get("status") or "check_unavailable"),
        "proof_status": proof_status,
        "surface": SURFACE,
        "language": language,
        # Until an HMAC-authenticated capsule is available, expose only the
        # public origin;
        # the exact path remains transient checker input rather than output.
        "target": check.get("checked_origin"),
        "finding": None,
        "evidence": None,
        "imperative": None,
        "acceptance": None,
        "recheck_url": None,
        "provenance": _provenance(check, language),
        "consent_receipt": None,
        "source_receipt": None,
        "measurement": check.get("measurement"),
        "score_percent": check.get("score_percent"),
        "coverage_percent": check.get("coverage_percent"),
        "errors": list(errors or []),
        "not_measured": list(check.get("not_measured") or []),
    }


