def _remedy_rows(signal_key: str,
                 target: str,
                 language: Language = "ar") -> tuple[RemedyOutput | None, str | None]:
    """يرجع (العلاج، سببَ غيابه). ولا يُسقط قياسةً صحيحةً حين يتعذّر العلاج.

    فالعلاجُ إضافةٌ فوق القياس لا شرطٌ له: عطلٌ في مولّد العلاج يجب أن يكلّف
    العميلَ كتلةَ لصقٍ لا نتيجتَه كلَّها.
    """
    unavailable = {
        "ar": "تعذّر توليد معالجة جاهزة للصق بأمان لهذه النتيجة",
        "en": "a paste-ready remedy could not be generated safely for this result",
    }[language]
    try:
        from . import readiness_remedy as rr
    except Exception:                                             # noqa: BLE001
        return None, unavailable
    try:
        raw = rr.remedy_for(signal_key, target, language)
    except Exception:                                             # noqa: BLE001
        return None, unavailable
    if raw is None:
        return None, (rr.explain_gap(signal_key, language) or unavailable)
    try:
        return RemedyOutput.model_validate(raw), None
    except ValidationError:
        return None, unavailable


def _provenance(check: dict[str, Any],
                language: Language = "ar") -> dict[str, Any] | None:
    """يُبنى من عدد الإشارات المقيسة فعلاً، لا من رقمٍ مكتوبٍ بيد.

    رقمٌ ثابتٌ في النصّ يكذب صامتاً أوّلَ ما تُضاف إشارةٌ أو تُحذف.
    """
    signals = check.get("signals")
    count = len(signals) if isinstance(signals, (list, dict)) else None
    if not count:
        return None
    return {
        "measured_by": "Advisors AI",
        "full_sheet_url": FULL_SHEET_URL.get(language, FULL_SHEET_URL["ar"]),
        "signals_measured": count,
        "signals_returned": 1,
    }


def _closed_measurement_result(
    check: dict[str, Any], language: Language,
) -> StoreReadinessOutput:
    status = str(check.get("status") or "check_unavailable")
    if status == "partial":
        row = _base_result(
            check, status="partial", proof_status="not_applicable",
            ok=False, language=language, errors=["measurement_partial"],
        )
    elif status == "target_rejected":
        row = _base_result(
            check, status="target_rejected", proof_status="not_applicable",
            ok=False, language=language,
            errors=list(check.get("errors") or ["target_rejected"]),
        )
    else:
        row = _base_result(
            check, status="check_unavailable", proof_status="not_applicable",
            ok=False, language=language, errors=["measurement_unavailable"],
        )
    return StoreReadinessOutput.model_validate(row)


def _normalise_capsule(
    check: dict[str, Any], cap: dict[str, Any], language: Language,
) -> StoreReadinessOutput:
    problems = _validate_proof(cap)
    if problems:
        raise RuntimeError("proof capsule validation failed")
    evidence_row = cap.get("evidence")
    finding_row = cap.get("finding")
    signals = {
        signal.get("key"): signal
        for signal in check.get("signals", [])
        if isinstance(signal, dict)
    }
    chosen = (
        signals.get(finding_row.get("signal_key"))
        if isinstance(finding_row, dict) else None
    )
    if (
        cap.get("surface") != SURFACE
        or cap.get("language") != language
        or cap.get("target") != check.get("checked_origin")
        or not isinstance(evidence_row, dict)
        or evidence_row.get("measurement") != check.get("measurement")
        or evidence_row.get("score_percent") != check.get("score_percent")
        or evidence_row.get("coverage_percent") != check.get("coverage_percent")
        or evidence_row.get("measured_at_utc") != check.get("measured_at_utc")
        or not isinstance(chosen, dict)
        or chosen.get("ok") is not False
        or not isinstance(chosen.get("weight"), int)
        or chosen["weight"] <= 0
    ):
        raise RuntimeError("proof capsule does not match its measurement")
    source_receipt = SourceReceiptOutput.model_validate(
        cap.get("source_receipt"))
    consent_receipt = ConsentReceiptOutput.model_validate(
        cap.get("consent_receipt"))
    finding = FindingOutput.model_validate(cap.get("finding"))
    evidence = EvidenceOutput.model_validate(evidence_row)
    row = _base_result(
        check, status="finding", proof_status="verified", ok=True,
        language=cap.get("language"),
    )
    # العلاجُ يُبنى على **أصلِ ما قِيس** لا على ما ورد في الطلب، فيبقى
    # مقيَّداً بما أثبتته القياسةُ نفسُها.
    remedy, why = _remedy_rows(
        finding.signal_key,
        str(cap.get("target") or ""),
        language,
    )
    row.update({
        "target": cap.get("target"),
        "finding": finding,
        "evidence": evidence,
        "imperative": cap.get("imperative"),
        "acceptance": cap.get("acceptance"),
        "remedy": remedy,
        "no_remedy_reason": why,
        "recheck_url": cap.get("recheck_url"),
        "consent_receipt": consent_receipt,
        "source_receipt": source_receipt,
    })
    return StoreReadinessOutput.model_validate(row)


def advisors_store_readiness_check(
    url: str,
    language: Language = "ar",
) -> StoreReadinessOutput:
    """Measure once, then build one verified proof capsule or fail closed."""
    try:
        measured = _measure_public_page(url, language)
    except Exception:  # public boundary: never expose an internal exception
        return _closed_measurement_result(
            {"status": "check_unavailable"}, language)

    check = measured.get("check")
    if not isinstance(check, dict):
        return _closed_measurement_result(
            {"status": "check_unavailable"}, language)
    if check.get("status") != "complete":
        return _closed_measurement_result(check, language)

    try:
        cap = measured.get("capsule")
        measured_proof_status = measured.get("proof_status")
        if measured_proof_status == "unavailable":
            if cap is not None:
                raise RuntimeError("unavailable proof carried a capsule")
            return StoreReadinessOutput.model_validate(_base_result(
                check, status="proof_unavailable", proof_status="unavailable",
                ok=False, language=language, errors=["proof_unavailable"],
            ))
        if cap is None:
            if measured_proof_status != "not_applicable":
                raise RuntimeError("proof state and capsule disagree")
            status: ToolStatus = (
                "ready" if check.get("readiness_passed") is True
                else "no_actionable_finding"
            )
            return StoreReadinessOutput.model_validate(_base_result(
                check, status=status, proof_status="not_applicable", ok=True,
                language=language,
            ))
        if not isinstance(cap, dict):
            raise RuntimeError("proof capsule returned a non-object")
        if measured_proof_status != "verified":
            raise RuntimeError("unverified proof capsule")
        return _normalise_capsule(check, cap, language)
    except Exception:
        # Missing signing material, a temporarily absent proof API, or a
        # malformed proof all have the same safe public result.  Exception
        # text is never reflected to the agent or merchant.
        return StoreReadinessOutput.model_validate(_base_result(
            check, status="proof_unavailable", proof_status="unavailable",
            ok=False, language=language, errors=["proof_unavailable"],
        ))


class StrictToolArguments:
    """Reject undeclared arguments before the SDK can discard them."""

    ERROR = "undeclared tool arguments are not allowed"

    def __init__(self, allowed: dict[str, frozenset[str]]):
        self.allowed = dict(allowed)

    async def __call__(self, ctx: ServerRequestContext,
                       call_next: CallNext) -> HandlerResult:
        if ctx.method == "tools/call" and isinstance(ctx.params, dict):
            name = str(ctx.params.get("name") or "")
            arguments = ctx.params.get("arguments") or {}
            expected = self.allowed.get(name)
            if expected is not None and isinstance(arguments, dict):
                if set(arguments) - expected:
                    raise MCPError(
                        code=INVALID_PARAMS,
                        message=self.ERROR,
                        data={"reason": "undeclared_arguments"},
                    )
        return await call_next(ctx)


