def _seal_input_contract() -> None:
    manager = mcp._tool_manager  # MCP SDK 2.0; dependency is pinned.
    registered = {tool.name for tool in manager.list_tools()}
    if registered != set(TOOL_ARGUMENTS):
        raise RuntimeError("store readiness tool inventory is not closed")
    tool = manager.get_tool(TOOL_NAME)
    if tool is None:
        raise RuntimeError("store readiness tool is unavailable")
    if set(tool.parameters.get("properties", {})) != TOOL_ARGUMENTS[TOOL_NAME]:
        raise RuntimeError("store readiness input fields drifted")
    tool.fn_metadata.arg_model.model_config["extra"] = "forbid"
    tool.fn_metadata.arg_model.model_rebuild(force=True)
    tool.parameters = tool.fn_metadata.arg_model.model_json_schema(by_alias=True)
    if tool.parameters.get("additionalProperties") is not False:
        raise RuntimeError("store readiness input schema is not closed")


_seal_input_contract()


@mcp.custom_route(HEALTH_PATH, methods=["GET"], include_in_schema=False)
@mcp.custom_route(
    INTERNAL_HEALTH_PATH, methods=["GET"], include_in_schema=False)
async def healthz(_request: Request) -> JSONResponse:
    return JSONResponse({
        "ok": True,
        "service": "advisors-ai-store-readiness",
        "version": VERSION,
        "surface": SURFACE,
        "tool_count": 1,
        "write_tools": 0,
        "recheck_method": "POST",
        "local_rate_limit": {
            "active": True,
            "max_requests": RATE_LIMIT_REQUESTS,
            "window_seconds": RATE_LIMIT_WINDOW_SECONDS,
            "protected_paths": [MCP_PATH, RECHECK_PATH],
            "scope": "per-client",
            "client_identity": (
                "socket-peer; cf-connecting-ip only from loopback proxy"
            ),
        },
        "edge_rate_limit_recommended": True,
    })


def _pairs_without_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    obj: dict[str, Any] = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError("duplicate JSON key")
        obj[key] = value
    return obj


def _error_response(status: Literal[
        "invalid_request", "receipt_rejected", "proof_unavailable"],
        error: str, http_status: int) -> JSONResponse:
    row = RecheckErrorOutput(ok=False, status=status, error=error)
    return JSONResponse(row.model_dump(mode="json"), status_code=http_status)


@mcp.custom_route(RECHECK_PATH, methods=["POST"], include_in_schema=False)
async def recheck(request: Request) -> JSONResponse:
    content_type = request.headers.get("content-type", "").split(";", 1)[0]
    if content_type.strip().lower() != "application/json":
        return _error_response(
            "invalid_request", "application_json_required", 415)
    length = request.headers.get("content-length")
    if length:
        try:
            if int(length) > MAX_RECHECK_BODY_BYTES:
                return _error_response(
                    "invalid_request", "request_body_too_large", 413)
        except ValueError:
            return _error_response(
                "invalid_request", "invalid_content_length", 400)
    body = await request.body()
    if len(body) > MAX_RECHECK_BODY_BYTES:
        return _error_response(
            "invalid_request", "request_body_too_large", 413)
    try:
        payload = json.loads(
            body.decode("utf-8"), object_pairs_hook=_pairs_without_duplicates)
        parsed = RecheckInput.model_validate(payload)
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError, ValidationError):
        return _error_response("invalid_request", "closed_contract_required", 400)

    try:
        module = _proof_module()
        verifier = getattr(module, "verify_recheck_request", None)
        if not callable(verifier):
            raise RuntimeError("recheck verifier unavailable")
        verified = verifier(
            parsed.url,
            parsed.source_receipt.model_dump(mode="json"),
            language=parsed.language,
        )
    except (RuntimeError, TypeError, ValueError):
        return _error_response("proof_unavailable", "proof_unavailable", 503)
    if verified is not True:
        return _error_response("receipt_rejected", "receipt_rejected", 403)

    result = advisors_store_readiness_check(parsed.url, parsed.language)
    return JSONResponse(result.model_dump(mode="json"))


class LocalRateLimit:
    """Small fixed-window guard for the two public, scan-triggering paths.

    It uses the socket peer address. ``CF-Connecting-IP`` is accepted only
    from a loopback peer, so a direct remote caller cannot mint buckets by
    spoofing a forwarding header.  The two limits are runtime-configurable
    for a deployment whose reverse proxy does not share the loopback network.
    """

    def __init__(
        self,
        app: ASGIApp,
        *,
        max_requests: int = RATE_LIMIT_REQUESTS,
        window_seconds: int = RATE_LIMIT_WINDOW_SECONDS,
    ) -> None:
        if max_requests < 1 or window_seconds < 1:
            raise ValueError("rate limit must be positive")
        self.app = app
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._buckets: OrderedDict[str, deque[float]] = OrderedDict()
        self._lock = threading.Lock()

    @staticmethod
    def _client_identity(scope: Scope) -> str:
        peer = scope.get("client")
        peer_text = str(peer[0]) if isinstance(peer, tuple) and peer else ""
        try:
            peer_address = ipaddress.ip_address(peer_text)
            peer_key = peer_address.compressed
        except ValueError:
            return "peer:unknown"

        if peer_address.is_loopback:
            forwarded = [
                value for name, value in scope.get("headers", [])
                if name.lower() == b"cf-connecting-ip"
            ]
            if len(forwarded) == 1:
                try:
                    candidate = ipaddress.ip_address(
                        forwarded[0].decode("ascii").strip())
                except (UnicodeDecodeError, ValueError):
                    candidate = None
                if candidate is not None and candidate.is_global:
                    return "cf:" + candidate.compressed
        return "peer:" + peer_key

    def _admit(self, client: str, moment: float) -> tuple[bool, int]:
        cutoff = moment - self.window_seconds
        with self._lock:
            expired = [
                key for key, values in self._buckets.items()
                if not values or values[-1] <= cutoff
            ]
            for key in expired:
                self._buckets.pop(key, None)
            if client not in self._buckets:
                if len(self._buckets) >= RATE_LIMIT_MAX_CLIENTS:
                    client = "__overflow__"
                self._buckets.setdefault(client, deque())
            values = self._buckets[client]
            while values and values[0] <= cutoff:
                values.popleft()
            self._buckets.move_to_end(client)
            if len(values) >= self.max_requests:
                retry_after = max(
                    1,
                    int(self.window_seconds - (moment - values[0])) + 1,
                )
                return False, retry_after
            values.append(moment)
            return True, 0

    async def __call__(
        self, scope: Scope, receive: Receive, send: Send,
    ) -> None:
        path = str(scope.get("path") or "").rstrip("/") or "/"
        protected = {MCP_PATH.rstrip("/"), RECHECK_PATH.rstrip("/")}
        if scope.get("type") != "http" or path not in protected:
            await self.app(scope, receive, send)
            return
        client = self._client_identity(scope)
        allowed, retry_after = self._admit(client, time.monotonic())
        if allowed:
            await self.app(scope, receive, send)
            return
        response = JSONResponse(
            {
                "ok": False,
                "status": "rate_limited",
                "error": "rate_limit_exceeded",
            },
            status_code=429,
            headers={"Retry-After": str(retry_after)},
        )
        await response(scope, receive, send)


class PostOnlyMCPTransport:
    """Reject dead standalone streams on this stateless MCP endpoint.

    The Python SDK 2.0 legacy transport still opens an indefinite SSE stream
    for a version-less ``GET`` even when ``stateless_http=True``.  This service
    has no session or server-initiated channel to feed such a stream, so the
    Streamable HTTP contract requires an immediate 405 instead.  Keep the
    gate outside the rate limiter: unsupported probes neither occupy a live
    connection nor consume a caller's POST allowance.
    """

    def __init__(
        self,
        app: ASGIApp,
        security_settings: TransportSecuritySettings,
    ) -> None:
        self.app = app
        self.security = TransportSecurityMiddleware(security_settings)

    async def __call__(
        self, scope: Scope, receive: Receive, send: Send,
    ) -> None:
        is_mcp = (
            scope.get("type") == "http"
            and scope.get("path") == MCP_PATH
        )
        if is_mcp:
            method = str(scope.get("method") or "").upper()
            request = Request(scope, receive=receive)
            rejection = await self.security.validate_request(
                request, is_post=(method == "POST"))
            if rejection is not None:
                await rejection(scope, receive, send)
                return
        if is_mcp and method != "POST":
            response = Response(
                content=b"",
                status_code=405,
                headers={"Allow": "POST"},
            )
            await response(scope, receive, send)
            return
        await self.app(scope, receive, send)


TRANSPORT_SECURITY = TransportSecuritySettings(
    allowed_hosts=[
        "advisorsai.ai",
        "advisorsai.ai:*",
        "localhost",
        "localhost:*",
        "127.0.0.1",
        "127.0.0.1:*",
    ],
    # Exact browser origins for the three intended surfaces.  Server-to-server
    # MCP clients normally omit Origin; unknown browser origins stay closed.
    allowed_origins=[
        "https://advisorsai.ai",
        "https://claude.ai",
        "https://chatgpt.com",
    ],
)

_transport_app = mcp.streamable_http_app(
    streamable_http_path=MCP_PATH,
    json_response=True,
    stateless_http=True,
    max_request_body_size=128 * 1024,
    transport_security=TRANSPORT_SECURITY,
    host="0.0.0.0",
)
app = PostOnlyMCPTransport(
    LocalRateLimit(_transport_app), TRANSPORT_SECURITY)


